import heapq
def dijk(g,s):
    d={n:float('inf')for n in g};d[s]=0
    pq=[(0,s)]
    while pq:
        dd,u=heapq.heappop(pq)
        if dd>d[u]:continue
        for v,w in g[u]:
            if d[u]+w<d[v]:
                d[v]=d[u]+w;heapq.heappush(pq,(d[v],v))
    return d

